/* Standalone visual prototype. Fictional in-memory records; no accounts, network, health prescription or native alarms. Appearance alone is saved in this browser. */
'use strict';
const $ = selector => document.querySelector(selector);
const icons = {
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  plan:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',
  train:'<path d="M3 9v6m3-9v12m12-12v12m3-9v6M6 12h12"/>',
  fuel:'<path d="M12 21c-5 0-8-5-8-9 0-4 4-6 8-3 4-3 8-1 8 3 0 4-3 9-8 9ZM12 8c0-4 3-6 6-6-1 4-3 6-6 6Z"/>',
  growth:'<path d="M4 20V4m0 16h17M8 15l4-5 4 2 5-7"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  leaf:'<path d="M5 19C1 7 14 4 21 3c-1 11-5 18-13 15M4 21 16 9"/>',
  book:'<path d="M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-6-2-10 1Zm0 0v15"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
  moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',
  upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
  bell:'<path d="M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9Zm4 12h4"/>',
  water:'<path d="M12 2C8 8 5 11 5 15a7 7 0 0 0 14 0c0-4-3-7-7-13Z"/>',
  shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn = (label,action,cls='button',extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const go = (label,view,cls='button') => `<button class="${cls}" data-view="${view}">${label}</button>`;
const state = {
  view:'today', theme:'night', calm:false, baseXP:80,
  complete:{}, partial:{}, setDone:{}, reps:{}, meals:[], water:0,
  planTab:'day', fuelTab:'log', growthTab:'overview', moved:false, imported:false,
  reflection:'', reflectionSaved:false, weeklySaved:false, timerRunning:false, timerRemaining:120,
  timerDeadline:0, round:1, isRest:false, timerFinished:false,
  onboardingStep:0, answers:{}, savedProfile:false, conflictResolved:false, offline:false,
  reminderPreview:false, goalTitle:'', shortlisted:false, focused:false
};
const tasks = [
  {id:'workout',title:'Movement & strength',category:'Strength',detail:'25 min · home session',xp:25,view:'train'},
  {id:'portfolio',title:'Build one portfolio case study',category:'Discipline',detail:'45 min · focused work',xp:15,view:'goals'},
  {id:'learn',title:'Practice camera fundamentals',category:'Knowledge',detail:'20 min · learning',xp:15,view:'growth'},
  {id:'walk',title:'A walk with room to think',category:'Recovery',detail:'20 min · easy movement',xp:15,view:'train'},
  {id:'reflection',title:'Reflect on the day',category:'Discipline',detail:'5 min · evening',xp:10,view:'review'}
];
const routes=[['today','Today','sun'],['plan','Plan','plan'],['train','Train','train'],['fuel','Fuel','fuel'],['growth','Growth','growth']];
const routeLabels={today:'Today',plan:'Plan',train:'Train',fuel:'Fuel',growth:'Growth',goals:'Your goals',review:'Reflection',weekly:'Weekly review',onboarding:'Shape your plan',imports:'Import review',settings:'Settings & devices'};
let toastTimer;
function notify(message){const e=$('#toast');e.textContent=message;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3500);}
function xp(){return state.baseXP+tasks.reduce((sum,t)=>sum+(state.complete[t.id]?t.xp:Math.floor(t.xp*(state.partial[t.id]||0))),0)+(state.weeklySaved?30:0);}
function level(){let remaining=xp(),n=1,cost=100;while(remaining>=cost){remaining-=cost;n++;cost=100+25*(n-1);}return {n,remaining,cost};}
function theme(name,persist=true){if(!['night','marble','journal'].includes(name))return;state.theme=name;Appearance.preset(name,persist);}
function nav(){for(const id of ['desktop-nav','mobile-nav']){$('#'+id).innerHTML=routes.map(([key,label,symbol])=>`<button data-view="${key}" class="${id==='desktop-nav'?'nav-button ':''}${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`).join('');}}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="buttons">${actions}</div>`:''}</div>`;}
function render(focus=false){nav();$('#breadcrumb').textContent=routeLabels[state.view]||'Today';$('#calm-toggle').innerHTML=icon('moon');$('#calm-toggle').setAttribute('aria-pressed',String(state.calm));$('#calm-toggle').setAttribute('aria-label',state.calm?'Disable calm mode':'Enable calm mode');document.body.classList.toggle('calm',state.calm);const views={today,plan,train,fuel,growth,goals,review,weekly,onboarding,imports,settings};$('#main').innerHTML=(views[state.view]||today)();if(focus){$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}}
function navigate(view){if(!(view in routeLabels))return;state.view=view;render(true);}
function levelCard(){const l=level();return `<section class="card level-card game-only" aria-label="Sample XP progress"><div class="level-disc" style="--level-progress:${100*l.remaining/l.cost}"><div class="level-number">${l.n}<small>LEVEL</small></div></div><div><p class="eyebrow">A PRACTICE, NOT A RACE</p><h2>${l.n===1?'A strong beginning':'Finding your rhythm'}</h2><p><strong data-xp>${xp()} XP</strong> earned in this preview</p><p>${l.cost-l.remaining} XP to Level ${l.n+1}</p></div></section>`;}
function questRows(){return tasks.map(t=>`<div class="quest-row ${state.complete[t.id]?'done':''}"><button class="check-wrap" data-action="complete" data-id="${t.id}" aria-label="${state.complete[t.id]?'Undo':'Complete'} ${t.title}" aria-pressed="${!!state.complete[t.id]}"><span class="check">${state.complete[t.id]?icon('check'):''}</span></button><div><p class="quest-title">${t.title}</p><div class="meta"><span><span class="category-dot ${t.category==='Recovery'?'green':''}"></span>${t.category}</span><span>·</span><span>${t.detail}</span>${state.partial[t.id]&&!state.complete[t.id]?'<span>· Half complete</span>':''}</div></div><div class="task-end"><span class="xp-chip game-only">+${t.xp} XP</span><button class="more-button" data-action="task-menu" data-id="${t.id}" aria-label="Options for ${t.title}">⋯</button></div></div>`).join('');}
function timeline(){return `<section class="card"><div class="card-title"><h2>A day with intention</h2>${go('View plan','plan','text-button')}</div><div class="timeline"><div class="timeline-item"><span class="timeline-time">07:30</span><div class="timeline-detail"><strong>Movement & strength</strong><span>${tasks[0].detail.split(' min')[0]} min · your next action</span></div></div><div class="timeline-item"><span class="timeline-time">09:00</span><div class="timeline-detail"><strong>Team catch-up</strong><span>30 min · locked appointment</span></div></div><div class="timeline-item"><span class="timeline-time">${state.moved?'11:00':'10:00'}</span><div class="timeline-detail"><strong>Portfolio case study</strong><span>45 min · deep work</span></div></div><div class="timeline-item"><span class="timeline-time">18:00</span><div class="timeline-detail"><strong>Family dinner</strong><span>60 min · protected time</span></div></div></div></section>`;}
function today(){const done=tasks.filter(t=>state.complete[t.id]).length;return heading('SAMPLE MONDAY · OCTOBER 5','Make today count.','A stronger body. A clearer mind. A life with intention.',btn(`${icon('plus')}<span class="button-label">Quick capture</span>`,'capture','button', 'aria-label="Quick capture"'))+`<div class="dashboard"><div class="stack"><section class="hero"><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 240 245" fill="none"><circle cx="144" cy="108" r="84" stroke="currentColor" stroke-width=".5"/><path d="M47 209h177M64 199h139M75 52h118v13H75zm7 14h104m-91 1v119m17-119v119m18-119v119m18-119v119m18-119v119m-83 1h112v12H82zM97 51l36-20 41 20" stroke="currentColor" stroke-width="2"/><path d="M42 190c-20-37-15-77 10-104m-5 78-16-8m18-10-18-13m23-6-16-17m23 0-12-18m150 96c23-37 21-71 2-99m-9 76 17-8m-14-10 18-13m-20-8 16-17m-21 0 10-18" stroke="currentColor" stroke-width="1.3"/></svg></div><div class="hero-content"><span class="pill">${icon('sun')} YOUR NEXT MOVE</span><h2>${state.complete.workout?'You showed up.':'Build strength.<br>Keep your promise.'}</h2><p>${state.complete.workout?'One meaningful action, complete. Let that be enough for this moment.':'A little practice today becomes a little more possibility tomorrow.'}</p><div class="hero-meta"><span>${icon('clock')} ${tasks[0].detail.split(' min')[0]} minutes</span><span>${icon('train')} At home</span></div>${go(`${state.complete.workout?'Review session':'Open workout'} ${icon('arrow')}`,'train','button primary')}</div></section><section class="card"><div class="section-row"><h2>Your daily quests</h2><span class="pill game-only">${done} of ${tasks.length} complete</span></div>${questRows()}</section><div class="capacity-card">${icon('leaf')}<div><strong>There’s room to breathe.</strong><p>2h 10m of flexible space in this sample day.</p></div>${btn('A lighter day','lighter','text-button')}</div></div><div class="stack">${levelCard()}${timeline()}<section class="card quote"><span class="label">A THOUGHT FOR TODAY</span><span class="quote-mark" aria-hidden="true">“</span><blockquote>Give your attention to the next good action.</blockquote><span class="tiny muted">ORIGINAL STOIC-INSPIRED REFLECTION</span><div class="action">Put your phone aside for the first ten minutes of your next session.</div>${go('Your evening reflection →','review','text-button')}</section></div></div>`;}
function plan(){return heading('YOUR TIME, WITH PURPOSE','A plan that fits your life.','Fixed commitments stay protected. Changes stay in your hands.',go(`${icon('upload')}<span class="button-label">Import schedule</span>`,'imports','button'))+`<div class="section-tabs" role="group" aria-label="Planning views">${['day','week','goals'].map(v=>btn(v==='goals'?'Goals & campaigns':v[0].toUpperCase()+v.slice(1),'plan-tab',state.planTab===v?'active':'',`data-value="${v}" aria-pressed="${state.planTab===v}"`)).join('')}</div>${state.planTab==='goals'?goalCards():`<div class="week-strip">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<div class="week-day ${i===0?'selected':''}">${d}<strong>${5+i}</strong></div>`).join('')}</div><div class="grid-2"><section class="card"><div class="card-title"><h2>${state.planTab==='week'?'Monday anchors · week preview':'Monday, October 5'}</h2><span class="pill">Sample schedule</span></div><div class="schedule-block"><time>07:30</time><div><h3>Movement & strength</h3><p>${tasks[0].detail}</p></div>${icon('train')}</div><div class="buffer">10 min · transition & recovery</div><div class="schedule-block locked"><time>09:00</time><div><h3>Team catch-up</h3><p>30 min · fixed commitment</p></div>${icon('lock')}</div><div class="schedule-block"><time data-portfolio-time>${state.moved?'11:00':'10:00'}</time><div><h3>Portfolio case study</h3><p>45 min · flexible</p></div>${btn('Move','move','text-button')}</div>${state.imported?'<div class="schedule-block"><time>14:00</time><div><h3>Research seminar</h3><p>60 min · confirmed sample import</p></div></div>':''}<div class="schedule-block locked"><time>18:00</time><div><h3>Family dinner</h3><p>60 min · protected time</p></div>${icon('lock')}</div><p class="tiny muted">Illustrative blocks only. The complete scheduler comes in Phase 4.</p></section><div class="stack"><section class="card"><p class="eyebrow">CAPACITY, BEFORE COMMITMENT</p><h2>You don’t have to do everything.</h2><p class="muted tiny">Choose what matters, then give it enough room.</p><div class="nutrition-summary"><div><strong>4h 15m</strong><span>planned focus & routines</span></div><div><strong>2h 10m</strong><span>flexible space</span></div></div><div class="callout">Family time and sleep stay protected.<p>New work starts with a capacity check.</p></div><div class="buttons section-gap">${btn('Preview a lighter day','lighter','button')}${go('View goals','goals','button ghost')}</div></section><section class="card"><div class="card-title"><h2>Planning inbox</h2>${btn('+ Capture','capture','text-button')}</div><div class="list-row"><div><h3>${state.goalTitle?escapeHTML(state.goalTitle):'Choose a weekend creative project'}</h3><p>Unscheduled · estimate time before adding</p></div>${icon('book')}</div>${go('Try an academic import →','imports','text-button')}</section></div></div>`}`;}
function goalCards(){return `<div class="grid-3">${[['book','Create a portfolio','A story that shows what you can do.',60,'3 of 5 milestones','2–4 weeks · sample estimate'],['train','Build movement confidence','Learn the basics. Show up consistently.',35,'2 of 6 milestones','Practice-based progress'],['sun','Make room for family','Protect time you want to remember.',75,'3 of 4 planned moments','Review each week']].map(([i,t,d,p,m,e])=>`<section class="card goal-card"><span class="goal-icon">${icon(i)}</span><h2>${t}</h2><p>${d}</p><div class="progress-track" aria-label="${p}% sample progress"><span style="width:${p}%"></span></div><div class="meta"><span>${m}</span></div><p class="tiny">${e}</p>${btn('Explore campaign →','goal-detail','text-button',`data-value="${escapeHTML(t)}"`)}</section>`).join('')}</div>`;}
function goals(){return heading('SMALL ACTIONS, MEANINGFUL DIRECTION','What are you building?','Your progress has a purpose beyond the points.',btn(`${icon('plus')}<span class="button-label">Add a goal</span>`,'capture','button primary'))+goalCards()+`<section class="card section-gap"><div class="card-title"><h2>From intention to action</h2><span class="pill">Example pathway</span></div><div class="grid-3"><div><span class="label">01 · GOAL</span><h3>Create a portfolio</h3><p class="muted tiny">Choose what a useful first version includes.</p></div><div><span class="label">02 · MILESTONE</span><h3>Finish one case study</h3><p class="muted tiny">A clear problem, your approach and the result.</p></div><div><span class="label">03 · NEXT ACTION</span><h3>Outline the story</h3><p class="muted tiny">45 minutes, with space already in your day.</p></div></div>${go('See it in your schedule →','plan','text-button')}</section>`;}
function train(){return heading('TRAIN WITH INTENTION','Strong starts here.','A session that fits your equipment, your time and your day.',btn(`${icon('clock')}<span class="button-label">Short on time?</span>`,'short-workout','button'))+`<div class="grid-2"><div class="stack"><section class="card"><div class="card-title"><div><p class="eyebrow">HOME · MOVEMENT PRACTICE</p><h2>Full-body foundations</h2></div><span class="pill game-only">25 XP</span></div><p class="muted tiny">Illustrative workout layout. Sets and repetitions below are fictional logging examples, not a prescribed program.</p><div class="buttons section-gap"><span class="pill">${tasks[0].detail.split(' min')[0]} min</span><span class="pill">Cables · bench · bodyweight</span></div><div class="list-row"><div><h3>Warm-up & movement check</h3><p>See how you feel before choosing today's effort.</p></div>${btn('View','exercise-detail','text-button', 'data-value="Warm-up & movement check"')}</div><div class="card-title section-gap"><div><h2>Cable row</h2><p class="tiny muted">Record your own comfortable load and repetitions.</p></div>${btn('Technique','exercise-detail','text-button','data-value="Cable row"')}</div><table class="workout-table"><thead><tr><th scope="col">SET</th><th scope="col">PREVIOUS</th><th scope="col">REPS</th><th scope="col">LOG</th></tr></thead><tbody>${[1,2,3].map(n=>`<tr><td>${n}</td><td class="muted">12 reps</td><td><input type="number" inputmode="numeric" min="0" max="100" aria-label="Repetitions for set ${n}" data-reps="${n}" value="${state.reps[n]||12}"></td><td><button class="set-check" data-action="set" data-value="${n}" aria-pressed="${!!state.setDone[n]}" aria-label="${state.setDone[n]?'Undo':'Log'} set ${n}">${icon('check')}</button></td></tr>`).join('')}</tbody></table><div class="list-row"><div><h3>Bodyweight movement</h3><p>Choose a suitable progression in the full app.</p></div>${btn('Options','exercise-detail','text-button','data-value="Movement alternatives"')}</div><div class="list-row"><div><h3>Cooldown & recovery</h3><p>Make room for rest in the same plan.</p></div>${icon('leaf')}</div><div class="buttons section-gap">${btn(state.complete.workout?'Session complete · undo':'Finish sample session','finish-workout','button primary')}${btn('Half a session counts','partial-workout','button ghost')}</div></section></div><div class="stack"><section class="card timer-card"><p class="eyebrow">HOME BOXING · TIMER PREVIEW</p><h2>Find your rhythm.</h2><p class="tiny muted">Shadowboxing & footwork · no contact</p><div class="timer-number" id="timer-number">${formatTimer()}</div><p class="tiny muted" id="timer-label">${timerLabel()}</p><div class="buttons section-gap">${btn(state.timerRunning?'Pause':state.timerFinished?'Finished':'Start timer','timer','button primary',state.timerFinished?'disabled':'')}${btn('Reset','reset-timer','button ghost')}</div><p class="tiny muted section-gap">2 sample rounds · 2 min / 1 min rest.<br>This preview does not create background alarms.</p></section><section class="card"><div class="card-title"><h2>Make it work for today.</h2>${icon('leaf')}</div><div class="list-row"><div><h3>Walking & recovery</h3><p>Simple movement belongs in the plan too.</p></div>${go('Plan','plan','text-button')}</div><div class="list-row"><div><h3>Equipment changed?</h3><p>Review alternatives before the session.</p></div>${btn('Adapt','exercise-detail','text-button','data-value="Equipment alternatives"')}</div></section><section class="card"><p class="eyebrow">LEARN TOGETHER</p><h2>Support a cheer flyer.</h2><p class="tiny muted">Start with qualified coaching, supervised practice and coach-approved preparation.</p>${btn('Explore the learning path →','cheer','text-button')}</section></div></div>`;}
const diets=[['Balanced','Food variety','A general comparison entry'],['Mediterranean','Food pattern','Compare foods and practicality'],['Higher protein','Nutrient emphasis','Review needs and suitability'],['Vegetarian / vegan','Food selection','Review nutrient adequacy'],['Low-carb / ketogenic','Food selection','Different levels of restriction'],['Intermittent fasting','Meal timing','Review suitability before choosing'],['OMAD','Meal timing','A restrictive option to research'],['Carnivore','Food selection','Evidence limitations matter'],['Liquid approaches','Four different categories','Medical liquids ≠ complete replacements']];
function fuel(){return heading('NOURISH YOUR PRACTICE','Food that supports your day.','Simple logging. Informed choices. No points for eating less.',btn(`${icon('plus')}<span class="button-label">Log a meal</span>`,'meal','button primary'))+`<div class="section-tabs" role="group" aria-label="Nutrition sections">${[['log','Daily log'],['compare','Compare approaches'],['prep','Recipes & prep']].map(([key,label])=>btn(label,'fuel-tab',state.fuelTab===key?'active':'',`data-value="${key}" aria-pressed="${state.fuelTab===key}"`)).join('')}</div>${state.fuelTab==='compare'?`<div class="callout">A comparison is a starting point, not a recommendation.<p>Timing, food choices and energy intake are different decisions. The full app will show evidence, limitations and personal suitability.</p></div><div class="grid-3 section-gap">${diets.map(([n,t,d])=>`<button class="diet-card" data-action="diet" data-value="${n}"><span class="label">${t}</span><strong>${n}</strong><small>${d} →</small></button>`).join('')}</div>`:state.fuelTab==='prep'?`<div class="grid-2"><section class="card"><p class="eyebrow">MAKE TOMORROW EASIER</p><h2>Saved meals & preparation</h2><div class="list-row"><div><h3>Roasted vegetable bowl</h3><p>Sample recipe · adjust ingredients and portions</p></div>${btn('Review','recipe','text-button')}</div><div class="list-row"><div><h3>Make a grocery list</h3><p>Confirm ingredients, allergies and quantities first.</p></div>${btn('Preview','grocery','text-button')}</div>${go('Find time to prepare →','plan','text-button')}</section><section class="card empty-state">${icon('book')}<h3>Your favorites, one tap away.</h3><p>The complete app will save recipes and combine ingredients into a grocery list.</p>${btn('Try a sample recipe','recipe','button')}</section></div>`:`<div class="grid-2"><section class="card"><div class="card-title"><h2>Today's meals</h2><span class="pill">${state.meals.length} logged</span></div>${state.meals.length?state.meals.map(m=>`<div class="list-row"><div class="meal-name"><span class="meal-icon">${icon('fuel')}</span><div><h3>${escapeHTML(m.name)}</h3><p>${escapeHTML(m.portion)} · sample log · nutrients not calculated</p></div></div>${icon('check')}</div>`).join(''):`<div class="empty-state">${icon('fuel')}<h3>Start with what you ate.</h3><p>Log a saved meal or a simple description. You can add detail when it helps.</p>${btn('Log your first sample meal','meal','button primary')}</div>`}<div class="callout section-gap">Your approach is yours to choose.<p>No calorie or fasting target is assumed. Missing personal context stays visible.</p></div></section><div class="stack"><section class="card"><div class="card-title"><h2>Water check-in</h2>${icon('water')}</div><div class="kpi">${state.water}<small> mL logged</small></div><p class="tiny muted">Preview log only. No daily target or electrolyte dose prescribed.</p>${btn('+ Log 250 mL','water','button')}</section><section class="card"><p class="eyebrow">A LITTLE CONTEXT HELPS</p><h2>How are you feeling?</h2><p class="tiny muted">Hunger, energy and digestion tell part of the story that numbers cannot.</p>${btn('Add a check-in','checkin','button ghost')}</section></div></div>`}`;}
function chart(){return `<svg class="chart" viewBox="0 0 400 150" role="img" aria-label="Fictional weekly walking minutes: 40, 60, 55, 80, 75, 95"><line x1="20" y1="30" x2="380" y2="30"/><line x1="20" y1="75" x2="380" y2="75"/><line x1="20" y1="120" x2="380" y2="120"/><polyline points="25,105 95,78 165,85 235,50 305,58 375,30"/>${[[25,105],[95,78],[165,85],[235,50],[305,58],[375,30]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5"/>`).join('')}<text x="20" y="145">Week 1</text><text x="180" y="145">Week 3</text><text x="343" y="145">Week 6</text></svg>`;}
function growth(){return heading('BECOMING, LITTLE BY LITTLE','Progress worth noticing.','See what is changing—and what the data cannot tell you yet.',go('Weekly review','weekly','button'))+`<div class="grid-3"><section class="card"><span class="label">PRACTICE DAYS · SAMPLE WEEK</span><div class="kpi">4 <small>of 7</small></div><p class="tiny muted">Consistency includes returning after a pause.</p></section><section class="card"><span class="label">MILESTONES · SAMPLE DATA</span><div class="kpi">3 <small>completed</small></div><p class="tiny muted">Meaningful steps toward a portfolio.</p></section><section class="card"><span class="label">LEARNING · SAMPLE WEEK</span><div class="kpi">80 <small>minutes</small></div><p class="tiny muted">Practice, review and real application.</p></section></div><div class="grid-2 section-gap"><section class="card"><div class="card-title"><h2>More room for movement</h2><span class="pill">Fictional trend</span></div><p class="tiny muted">Weekly walking minutes · six illustrative weeks</p>${chart()}<div class="callout section-gap">Real outcomes have their own evidence.<p>Health measurements and goal forecasts are separate from XP. No body-goal arrival date without sufficient data.</p></div>${btn('Inspect assumptions','assumptions','text-button')}</section><section class="card game-only"><div class="card-title"><h2>Your character, in practice</h2><span class="pill">Sample attributes</span></div>${[['Strength',55],['Endurance',40],['Discipline',72],['Knowledge',65],['Recovery',60]].map(([n,v])=>`<div class="attribute"><span>${n}</span><span>${v}</span></div><div class="progress-track"><span style="width:${v}%"></span></div>`).join('')}<p class="tiny muted section-gap">Attributes celebrate actions; they are not health scores.</p>${btn('Choose a personal reward','reward','text-button')}</section><section class="card"><div class="card-title"><h2>Keep learning</h2>${go('All goals','goals','text-button')}</div><div class="list-row"><div><h3>Photography foundations</h3><p>Practice exposure · then review your own photos.</p></div>${btn('Open path','learning','text-button')}</div><div class="list-row"><div><h3>Practical home skills</h3><p>Find the right manual before following a procedure.</p></div>${btn('Explore','learning','text-button')}</div></section><section class="card empty-state">${icon('shield')}<h3>Photos are optional.</h3><p>Your progress does not need a photo. Private photo storage and consent will be implemented and tested later.</p>${go('Privacy controls','settings','button ghost')}</section></div>`;}
function review(){return heading('CLOSE THE DAY WITH INTENTION','Notice. Learn. Begin again.','A reflection is a chance to understand yourself, not to score your worth.')+`<div class="grid-2"><section class="card quote"><p class="eyebrow">ORIGINAL STOIC-INSPIRED REFLECTION</p><blockquote>You cannot repeat this day. You can carry its lesson into tomorrow.</blockquote><div class="action">Name one action within your control. Give it a little more care tomorrow.</div></section><section class="card"><h2>What was in your control today?</h2><label class="field"><span>One thing you did, and one thing you learned</span><textarea id="reflection-input" placeholder="I made time for…">${escapeHTML(state.reflection)}</textarea></label><p class="tiny muted">Use fictional text in this preview. Nothing is sent or saved after refresh.</p>${btn(state.reflectionSaved?'Reflection recorded · 10 XP':'Record reflection · 10 XP','save-reflection','button primary',state.reflectionSaved?'disabled':'')}${go('Back to Today','today','text-button')}</section></div>`;}
function weekly(){return heading('A WEEK IS A CHANCE TO ADJUST','Keep what works. Make room.','Review your time, energy and progress together.')+`<div class="grid-2"><section class="card"><p class="eyebrow">SAMPLE WEEK · OCT 5–11</p><h2>A little more consistent.</h2><div class="review-stat"><span>${icon('check')}</span><div><p>Four days of meaningful action</p><small>Small, repeatable steps are worth keeping.</small></div></div><div class="review-stat"><span>${icon('leaf')}</span><div><p>Family time stayed protected</p><small>A plan should make room for your life.</small></div></div><div class="review-stat"><span>${icon('clock')}</span><div><p>One focus block needed more time</p><small>Try a realistic estimate next week.</small></div></div><p class="tiny muted section-gap">These observations are fictional examples.</p></section><section class="card"><h2>One adjustment for next week</h2><label class="checkbox-row"><input type="checkbox" checked id="weekly-adjust"> Add a 10-minute buffer after focused work</label><p class="tiny muted">A suggestion to review; fixed commitments stay locked.</p><label class="field"><span>Did the plan help you do what mattered?</span><select id="usefulness"><option>Choose a sample answer</option>Yes, it helped</option>Somewhat</option>It needs to change</option></select></label>${btn(state.weeklySaved?'Review complete · 30 XP':'Finish sample review · 30 XP','save-weekly','button primary',state.weeklySaved?'disabled':'')}${go('Review next week’s plan →','plan','text-button')}</section></div>`;}
const questionGroups=[
  {title:'What deserves your time?',intro:'Be specific. A full calendar is not the same as a meaningful life.',questions:[['goal','Your most important goal','Build a creative portfolio'],['success','What would a useful first milestone look like?','Finish one case study'],['priority','What wins when time is tight?','Family and health'],['deadline','What deadline is genuinely fixed?','Unknown']]},
  {title:'Give your day some room.',intro:'We need the day you actually have, not the one you wish you had.',questions:[['obligations','Fixed work, school or family commitments','Add later'],['sleep','Preferred sleep window','23:00–07:00'],['minutes','Time for a sample morning session','25 minutes'],['obstacles','What usually gets in the way?','Overplanning']]},
  {title:'Build around your starting point.',intro:'Optional health context belongs in the real private onboarding. Use sample answers here.',questions:[['body','What health or performance goal matters?','Movement confidence'],['baseline','Which baseline measurements will you use?','Skip'],['screening','Health restrictions or clinician instructions?','Unknown'],['history','Current activity and training experience','Beginner sample']]},
  {title:'Make the plan practical.',intro:'Preferences and limitations shape the options. They do not need to be perfect.',questions:[['equipment','Available equipment','Cables, bench and bodyweight'],['food','Food preferences, allergies and cooking access','Review later'],['diet','Eating approach you want to research','Balanced or OMAD comparison'],['learning','What do you want to learn or create?','Photography']]},
  {title:'Make this your practice.',intro:'Choose how the app supports you. You can change every answer later.',questions:[['data','Comfort with photos, files and measurements','Photos optional'],['devices','Devices and notification preferences','Phone and Windows; quiet evenings'],['tone','Coaching tone','Direct and respectful'],['reward','A reward you would enjoy','An afternoon outdoors']]}
];
function onboarding(){const step=state.onboardingStep,g=questionGroups[step];return heading('A PLAN STARTS WITH CONTEXT','Let’s make it fit.','20 areas, five small steps. Skip, pause and edit any answer.')+`<div class="onboard-layout"><aside class="steps" aria-label="Setup progress">${questionGroups.map((q,i)=>`<p class="${step===i?'active':''}"><span>${i+1}</span>${['Goals & priorities','Time & routine','Your starting point','Practical preferences','Support & rewards'][i]}</p>`).join('')}<p class="tiny muted">Fictional setup preview.<br>Use sample details only.</p></aside><section class="card form-card"><span class="pill">Step ${step+1} of 5</span><h2>${g.title}</h2><p>${g.intro}</p>${g.questions.map(([key,label,sample])=>`<label class="field"><span>${label}</span>${key==='minutes'?`<select data-answer="${key}"><option ${state.answers[key]==='15 minutes'?'selected':''}>15 minutes</option><option ${!state.answers[key]||state.answers[key]==='25 minutes'?'selected':''}>25 minutes</option><option ${state.answers[key]==='45 minutes'?'selected':''}>45 minutes</option><option ${state.answers[key]==='Unknown'?'selected':''}>Unknown</option></select>`:`<input data-answer="${key}" value="${escapeHTML(state.answers[key]||'')}" placeholder="${sample}" autocomplete="off">`}</label>`).join('')}<div class="form-actions"><div class="buttons">${step?btn('Back','onboard-back','button ghost'):go('Pause setup','today','button ghost')}${btn('Skip this group','onboard-skip','text-button')}</div>${btn(step===4?'Preview my plan':'Continue →','onboard-next','button primary')}</div></section></div>`;}
function imports(){return heading('REFERENCE → REVIEW → PLAN','Bring your plans together.','Review the facts before anything changes your schedule.')+`<div class="grid-2"><section class="card"><div class="card-title"><h2>Sample academic schedule</h2><span class="pill">Fictional PDF preview</span></div><div class="file-preview"><p class="eyebrow">SAMPLE UNIVERSITY · RESEARCH METHODS</p><h3>October seminar schedule</h3><p class="tiny">Monday, October 5 · 14:00–15:00</p><div class="file-line"></div><div class="file-line short"></div><p class="tiny">Draft submission: 10/09</p><div class="file-line"></div><p class="tiny muted">Timezone and date format not provided.</p></div><p class="tiny muted section-gap">This is a built-in sample, not an uploaded or parsed file. Real file processing comes in Phase 6A.</p></section><section class="card"><h2>Confirm the extracted facts</h2><label class="fact-row"><input id="import-seminar" type="checkbox" checked ${state.imported?'disabled':''}><span><strong>Research seminar · Oct 5, 14:00</strong><small>Page 1 · 60 minutes · confirm the timezone below</small></span></label><div class="fact-row">${icon('clock')}<div><strong>Draft submission: 10/09</strong><small>Could mean October 9 or September 10. This candidate remains excluded.</small><span class="pill gold">Needs clarification</span></div></div><label class="field"><span>Timezone for the confirmed seminar</span><select id="import-zone"><option value="">Select a timezone</option><option value="America/Denver">America/Denver</option><option value="America/New_York">America/New_York</option></select></label><div class="callout">Only checked, unambiguous facts can enter the plan.<p>The deadline and resubmission permission remain unknown.</p></div><div class="buttons section-gap">${btn(state.imported?'Seminar added to sample plan':'Preview calendar changes','preview-import','button primary',state.imported?'disabled':'')}${go('Cancel','plan','button ghost')}</div></section></div>`;}
function settings(){return heading('YOUR DATA. YOUR CHOICES.','A little peace of mind.','Your appearance, privacy and daily preferences in one place.')+Appearance.markup()+`<div class="grid-2"><section class="card"><div class="card-title"><h2>Devices & automatic sync</h2><span class="pill">Simulation only</span></div><p class="tiny muted">Required for launch. This prototype has no account or sync service.</p><div class="list-row"><div><h3>iPhone · sample device</h3><p>${state.offline?'Offline preview · changes would queue':'Foreground sync preview'}</p></div>${icon('sun')}</div><div class="list-row"><div><h3>Windows PC · sample device</h3><p>${state.conflictResolved?'Sample conflict resolved':'One schedule conflict to review'}</p></div>${btn('Review','sync-conflict','text-button')}</div><div class="buttons section-gap">${btn(state.offline?'Show connected state':'Show offline state','offline','button')}${btn('How sync works','sync-info','button ghost')}</div></section><section class="card"><div class="card-title"><h2>Reminders & quiet hours</h2>${icon('bell')}</div><div class="list-row"><div><h3>Reminders on this device</h3><p>${state.reminderPreview?'Preview preference: enabled':'Preview preference: disabled'}</p></div>${btn(state.reminderPreview?'Turn off':'Try enabling','reminders','text-button')}</div><p class="tiny muted">No OS permission or alarm is created here. Delivery must be tested on real devices in the working app.</p><label class="field"><span>Sample quiet hours</span><input value="21:00–07:00" aria-label="Sample quiet hours"></label></section><section class="card"><h2>Your private space</h2><div class="list-row"><div><h3>External AI sharing</h3><p>Off · an explicit data preview would come first.</p></div>${icon('lock')}</div><div class="list-row"><div><h3>Progress photos</h3><p>Optional · separate storage and sync consent.</p></div>${icon('shield')}</div>${btn('Preview backup & restore','backup','text-button')}</section><section class="card"><h2>Make it feel right</h2>${go("Edit profile & preferences","onboarding","text-button")}<div class="list-row"><div><h3>Calm mode</h3><p>Reduce game displays and motion.</p></div>${btn(state.calm?'Turn off':'Turn on','calm','button ghost')}</div><div class="list-row"><div><h3>Coaching tone</h3><p>Specific and respectful, at your preferred intensity.</p></div></div><select aria-label="Coaching tone"><option>Gentle</option><option selected>Direct</option><option>Grill me</option></select></section></div>`;}
function openDialog(title,content){$('#dialog-content').innerHTML=`<div class="dialog-header"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${content}`;$('#dialog').setAttribute('aria-label',title);$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
$('#dialog').addEventListener('keydown',e=>{
  if(e.key!=='Tab')return;
  const controls=Array.from($('#dialog').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]'));
  const first=controls[0],last=controls[controls.length-1];
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();if(last instanceof HTMLElement)last.focus();}
  if(!e.shiftKey&&document.activeElement===last){e.preventDefault();if(first instanceof HTMLElement)first.focus();}
});
function saveAnswers(skip=false){const group=questionGroups[state.onboardingStep];for(const [key] of group.questions){const e=$(`[data-answer="${key}"]`);state.answers[key]=skip?'Skipped':e.value.trim()||'Unknown';}}
function formatTimer(){return `${String(Math.floor(state.timerRemaining/60)).padStart(2,'0')}:${String(state.timerRemaining%60).padStart(2,'0')}`;}
function timerLabel(){return state.timerFinished?'Practice timer complete':`Round ${state.round} of 2 · ${state.isRest?'rest':'practice'}${state.timerRunning?'':' · paused'}`;}
function tick(){if(!state.timerRunning)return;state.timerRemaining=Math.max(0,Math.ceil((state.timerDeadline-Date.now())/1000));if(state.timerRemaining===0){state.timerRunning=false;if(state.round===2&&!state.isRest){state.timerFinished=true;notify('Sample timer finished. Log any completed practice yourself.');}else if(!state.isRest){state.isRest=true;state.timerRemaining=60;}else{state.round++;state.isRest=false;state.timerRemaining=120;}if(state.view==='train')render();}const number=$('#timer-number'),label=$('#timer-label');if(number)number.textContent=formatTimer();if(label)label.textContent=timerLabel();}
setInterval(tick,250);
document.addEventListener('input',e=>{const t=e.target;if(t instanceof HTMLInputElement&&t.dataset.reps)state.reps[t.dataset.reps]=t.value;if(t instanceof HTMLTextAreaElement&&t.id==='reflection-input')state.reflection=t.value;if((t instanceof HTMLInputElement||t instanceof HTMLSelectElement)&&t.dataset.answer)state.answers[t.dataset.answer]=t.value;});
document.addEventListener('click',e=>{
  const target=e.target instanceof Element?e.target.closest('button,a'):null;if(!target)return;
  if(target.hasAttribute('data-theme-option')){theme(target.getAttribute('data-theme-option'));return;}
  if(target.hasAttribute('data-view')){e.preventDefault();navigate(target.getAttribute('data-view'));return;}
  if(target.id==='calm-toggle'){state.calm=!state.calm;render();notify(state.calm?'Calm mode enabled. Your progress still counts.':'Game details restored.');return;}
  if(target.matches('.brand')){e.preventDefault();navigate('today');return;}
  const action=target.getAttribute('data-action'),value=target.getAttribute('data-value'),id=target.getAttribute('data-id');
  if(!action)return;
  switch(action){
    case 'close':closeDialog();break;
    case 'calm':state.calm=!state.calm;render();break;
    case 'complete':{const t=tasks.find(t=>t.id===id);state.complete[id]=!state.complete[id];state.partial[id]=0;if(id==='reflection')state.reflectionSaved=!!state.complete[id];render();notify(state.complete[id]?`${t.title} complete · +${t.xp} XP`:`Completion undone · ${t.xp} XP reversed`);break;}
    case 'task-menu':{const t=tasks.find(t=>t.id===id);openDialog(t.title,`<p>Make this action work for today. Your valid earned points stay yours.</p><div class="buttons">${go('Open activity',t.view,'button primary')}${btn('Record half complete','half-task','button',`data-id="${id}"`)}${btn('Find another time','move','button ghost')}</div>`);break;}
    case 'half-task':state.complete[id]=false;state.partial[id]=.5;closeDialog();render();notify('Partial completion recorded once in this preview.');break;
    case 'move':if($('#dialog').open)closeDialog();openDialog('A change you can review.',`<p>Move the portfolio focus session into an open sample slot. Locked commitments are unchanged.</p><div class="delta-row"><span>CURRENT</span>${state.moved?'11:00':'10:00'}–${state.moved?'11:45':'10:45'} · Portfolio case study</div><div class="delta-row"><span>PROPOSED</span>${state.moved?'10:00':'11:00'}–${state.moved?'10:45':'11:45'} · 45 min + 10 min buffer</div><p>Sample conflict check: the proposed slot is free. No change is applied until you accept.</p><div class="buttons">${btn('Accept move','accept-move','button primary')}${btn('Keep current plan','close','button ghost')}</div>`);break;
    case 'accept-move':state.moved=!state.moved;closeDialog();render();notify('Sample schedule updated. Move it back to undo.');break;
    case 'lighter':openDialog('A lighter day still counts.',`<p>Keep the essentials. Let the rest wait without turning tomorrow into a backlog.</p><div class="list-row"><div><h3>Keep your fixed commitments</h3><p>Family dinner and your meeting stay protected.</p></div>${icon('lock')}</div><div class="list-row"><div><h3>Choose a shorter session</h3><p>Review a 15-minute option before changing the plan.</p></div>${icon('leaf')}</div><div class="buttons">${btn('Preview shorter workout','short-workout','button primary')}${btn('Leave today as it is','close','button ghost')}</div>`);break;
    case 'short-workout':if($('#dialog').open)closeDialog();openDialog('Make room for a smaller start.',`<p>A shorter session would replace the planned workout, not become an extra task. Program details depend on your history and screening.</p><div class="delta-row"><span>SAMPLE ALTERNATIVE</span>25-minute session → 15-minute practice</div><p>This view demonstrates choosing an alternative. It does not prescribe an exercise dose.</p><div class="buttons">${btn('Use shorter sample session','accept-short','button primary')}${btn('Keep original','close','button ghost')}</div>`);break;
    case 'accept-short':tasks[0].detail='15 min · shorter sample';closeDialog();render();notify('Shorter sample selected; fixed appointments stay protected.');break;
    case 'plan-tab':state.planTab=value;render();break;
    case 'fuel-tab':state.fuelTab=value;render();break;
    case 'capture':openDialog('Make space for an idea.',`<p>Capture now. Choose a realistic time later.</p><label class="field"><span>What would you like to do?</span><input id="capture-title" placeholder="A small next step…" maxlength="100"></label><div class="buttons">${btn('Add to planning inbox','save-capture','button primary')}${btn('Cancel','close','button ghost')}</div>`);break;
    case 'save-capture':{const t=$('#capture-title').value.trim();if(!t){notify('Add a short title first.');$('#capture-title').focus();break;}state.goalTitle=t;closeDialog();navigate('plan');notify('Captured in the sample inbox. No time assigned.');break;}
    case 'goal-detail':openDialog(escapeHTML(value),`<p>A campaign connects your outcome to milestones and a realistic next action.</p><div class="delta-row"><span>NEXT MILESTONE</span>Finish one useful piece of work</div><p>Sample forecast: 2–4 weeks. Assumes 3–5 available hours each week and an unchanged scope. It is not a guarantee.</p><div class="buttons">${go('See the next action','plan','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'set':state.setDone[value]=!state.setDone[value];render();notify(state.setDone[value]?`Set ${value} logged in this preview.`:`Set ${value} log undone.`);break;
    case 'finish-workout':state.complete.workout=!state.complete.workout;state.partial.workout=0;render();notify(state.complete.workout?'Sample workout complete · 25 XP':'Workout completion undone · 25 XP reversed');break;
    case 'partial-workout':state.complete.workout=false;state.partial.workout=.5;render();notify('Half complete · 12 XP. Finishing adds the remaining 13.');break;
    case 'exercise-detail':openDialog(escapeHTML(value),`<p>The full app pairs accessible instructions with verified technique resources, appropriate alternatives and your confirmed equipment.</p><div class="callout">Technique content is not prescribed in this visual prototype.<p>Exercise suitability, sets, intensity and progression require the health/training implementation phase.</p></div><div class="buttons">${btn('Back to session','close','button primary')}</div>`);break;
    case 'timer':if(state.timerRunning){tick();state.timerRunning=false;}else if(!state.timerFinished){state.timerDeadline=Date.now()+state.timerRemaining*1000;state.timerRunning=true;}render();break;
    case 'reset-timer':state.timerRunning=false;state.timerRemaining=120;state.round=1;state.isRest=false;state.timerFinished=false;render();break;
    case 'cheer':openDialog('Learn with a qualified coach.',`<p>Your family goal becomes a learning pathway, with supervision and prerequisites kept visible.</p><div class="review-stat"><span>1</span><p>Find qualified cheer instruction.</p></div><div class="review-stat"><span>2</span><p>Review your coach’s requirements for basing and spotting.</p></div><div class="review-stat"><span>3</span><p>Schedule supervised practice and coach-approved home preparation.</p></div><p>Watching a video or earning points does not clear anyone to perform a stunt.</p><div class="buttons">${btn('Save sample learning interest','save-cheer','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'save-cheer':closeDialog();notify('Coached learning interest saved for this preview.');break;
    case 'meal':openDialog('Log what you ate.',`<p>A simple description is enough to start. Use fictional entries in this preview.</p><label class="field"><span>Meal</span><input id="meal-name" value="Vegetable & grain bowl" maxlength="100"></label><label class="field"><span>Portion or notes</span><input id="meal-portion" value="One bowl · sample entry" maxlength="140"></label><p>Nutrients are not estimated from this description. Meal logging does not reward restriction.</p><div class="buttons">${btn('Save sample meal','save-meal','button primary')}${btn('Cancel','close','button ghost')}</div>`);break;
    case 'save-meal':{const name=$('#meal-name').value.trim(),portion=$('#meal-portion').value.trim();if(!name){notify('Enter a meal name first.');break;}state.meals.push({name,portion});closeDialog();render();notify('Meal recorded in the preview.');break;}
    case 'water':state.water+=250;render();notify('250 mL recorded · no XP award.');break;
    case 'checkin':openDialog('A little context for today.',`<label class="field"><span>Energy</span><select><option>Steady</option><option>Low</option><option>High</option><option>Unknown</option></select></label><label class="field"><span>Anything worth noticing?</span><textarea placeholder="Use a sample note…"></textarea></label><div class="buttons">${btn('Record sample check-in','save-checkin','button primary')}</div>`);break;
    case 'save-checkin':closeDialog();notify('Sample check-in acknowledged. Real logging comes in Phase 5.');break;
    case 'diet':openDialog(escapeHTML(value),`<p>Compare evidence and practicality before choosing an approach. This card previews the information structure, not a personal recommendation.</p>${value==='Liquid approaches'?'<div class="callout">Separate entries: medically prescribed clear liquids; full liquids; nutritionally complete meal replacements; commercial liquid weight-loss programs.</div>':''}<div class="list-row"><div><h3>What it involves</h3><p>Meal timing, food selection and energy intake shown separately.</p></div></div><div class="list-row"><div><h3>Evidence and limitations</h3><p>Primary citations, publication dates and review dates accompany the complete entry.</p></div></div><div class="list-row"><div><h3>Personal fit</h3><p>Health screening, training needs, food access and adherence.</p></div></div><p>Restrictive approaches may require professional guidance. No target or fasting window is assigned by this preview.</p><div class="buttons">${btn('Add to sample comparison shortlist','shortlist','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'shortlist':state.shortlisted=true;closeDialog();notify('Added to the preview shortlist; no diet plan activated.');break;
    case 'recipe':openDialog('A recipe that fits your day.',`<p>Sample: roasted vegetables with a grain and your chosen protein source. Portions and substitutions are reviewed before any nutrient calculation.</p><label class="field"><span>Sample servings</span><select><option>1 serving</option><option>2 servings</option><option>4 servings</option></select></label><div class="buttons">${btn('Preview grocery list','grocery','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'grocery':if($('#dialog').open)closeDialog();openDialog('One simple grocery list.',`<p>Illustrative ingredients. Quantities, allergies and substitutions require confirmation in the complete flow.</p><label class="checkbox-row"><input type="checkbox"> Vegetables of your choice</label><label class="checkbox-row"><input type="checkbox"> Grain of your choice</label><label class="checkbox-row"><input type="checkbox"> Suitable protein source</label><div class="buttons">${go('Find preparation time','plan','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'assumptions':openDialog('See the story behind the chart.',`<p>The six plotted values are fictional walking minutes: 40, 60, 55, 80, 75 and 95. They show the visual design only.</p><p>Real measurements will show dates, units, source, missingness and trends. Forecasts will explain their inputs and uncertainty. XP does not enter those calculations.</p><div class="buttons">${btn('Understood','close','button primary')}</div>`);break;
    case 'reward':openDialog('Choose something worth enjoying.',`<p>A personal reward celebrates your practice without controlling food or exercise.</p><label class="field"><span>Sample reward</span><input value="An afternoon exploring a new place" maxlength="100"></label><div class="buttons">${btn('Save preview reward','save-reward','button primary')}</div>`);break;
    case 'save-reward':closeDialog();notify('Sample reward acknowledged for design review.');break;
    case 'learning':openDialog('Learn. Practice. Apply.',`<p>Example: photography fundamentals.</p><div class="review-stat"><span>1</span><p>Understand exposure and your camera controls.</p></div><div class="review-stat"><span>2</span><p>Practice with one subject in different light.</p></div><div class="review-stat"><span>3</span><p>Review your own photos and plan the next practice.</p></div><p>Verified tutorials, estimated time, materials and free/paid labels arrive with the content phase. No fabricated resource links appear here.</p><div class="buttons">${go('See learning in the plan','plan','button primary')}${btn('Close','close','button ghost')}</div>`);break;
    case 'save-reflection':if(!state.reflection.trim()){notify('Write a short sample reflection first.');$('#reflection-input').focus();break;}state.reflectionSaved=true;state.complete.reflection=true;render();notify('Reflection recorded · 10 XP, once.');break;
    case 'save-weekly':state.weeklySaved=true;render();notify('Sample weekly review complete · 30 XP. No schedule change was applied.');break;
    case 'onboard-back':saveAnswers();state.onboardingStep=Math.max(0,state.onboardingStep-1);render();break;
    case 'onboard-next':case 'onboard-skip':saveAnswers(action==='onboard-skip');if(state.onboardingStep<4){state.onboardingStep++;render();}else{state.savedProfile=true;const minutes=state.answers.minutes||'Unknown';openDialog('Here’s how your answers shape the plan.',`<p>Sample goal: ${escapeHTML(state.answers.goal||'Unknown')}.</p><div class="delta-row"><span>AVAILABLE MORNING TIME</span>${escapeHTML(minutes)}</div><p>${minutes==='15 minutes'?'A shorter-session option replaces the longer sample workout. No additional session is added.':'Your available time remains visible before any session is scheduled.'}</p><p>Unanswered health questions stay unknown. This setup does not generate a personal diet or exercise prescription.</p><div class="buttons">${btn('Use this sample day','accept-onboarding','button primary')}${btn('Keep editing','close','button ghost')}</div>`);}break;
    case 'accept-onboarding':if(state.answers.minutes==='15 minutes')tasks[0].detail='15 min · from sample preferences';closeDialog();navigate('today');notify('Sample preferences applied. Real personalization is still future work.');break;
    case 'preview-import':{const zone=$('#import-zone').value;if(!$('#import-seminar').checked){notify('Choose the seminar fact to preview a change.');break;}if(!zone){notify('Confirm a timezone before adding the seminar.');$('#import-zone').focus();break;}openDialog('One confirmed change.',`<p>Add Research seminar to the sample Monday at 14:00–15:00 (${escapeHTML(zone)}). The sample slot is free.</p><div class="callout">1 seminar selected · 1 ambiguous deadline excluded.<p>No resubmission permission is inferred.</p></div><div class="buttons">${btn('Confirm and add seminar','accept-import','button primary')}${btn('Back to review','close','button ghost')}</div>`);break;}
    case 'accept-import':state.imported=true;closeDialog();navigate('plan');notify('Confirmed seminar added once to the sample calendar.');break;
    case 'offline':state.offline=!state.offline;render();notify(state.offline?'Offline preview. A real app would queue changes locally.':'Connected preview. No actual server is contacted.');break;
    case 'sync-conflict':openDialog('Two devices, one decision.',`<p>Sample conflict: the same focus session was edited while two devices were offline.</p><div class="delta-row"><span>IPHONE CHANGE</span>Portfolio case study · 10:00</div><div class="delta-row"><span>WINDOWS CHANGE</span>Portfolio case study · 11:00</div><p>Choose one explicitly. Neither device silently overwrites the other.</p><div class="buttons">${btn('Keep 10:00','resolve-sync','button', 'data-value="early"')}${btn('Keep 11:00','resolve-sync','button primary','data-value="late"')}</div>`);break;
    case 'resolve-sync':state.moved=value==='late';state.conflictResolved=true;closeDialog();render();notify('Preview conflict resolved. No cross-device sync occurred.');break;
    case 'sync-info':openDialog('Local first. Connected when available.',`<p>In the working app, actions save locally and sync automatically when connected. Conflicting edits require review; duplicate completions earn XP once.</p><p>Phone background restrictions can delay remote schedule updates. Last-sync time and pending changes stay visible. This prototype simulates those screens only.</p><div class="buttons">${btn('Close','close','button primary')}</div>`);break;
    case 'reminders':state.reminderPreview=!state.reminderPreview;render();notify('Preview preference changed. No notification permission requested.');break;
    case 'backup':openDialog('Recovery should feel understandable.',`<p>The working app will export a complete versioned backup, inspect it before restoration, and show which records would change.</p><div class="callout">Preview checklist<p>Goals · schedule · logs · XP ledger · selected attachments.<br>Passwords and tokens are excluded.</p></div><p>No backup, encryption or restoration is implemented in this visual prototype.</p><div class="buttons">${btn('Close','close','button primary')}</div>`);break;
  }
});
// Native dialog handles focus trapping and Escape. Close it before a dialog navigation action renders another view.
document.addEventListener('click',e=>{const t=e.target instanceof Element?e.target.closest('[data-view]'):null;if(t&&$('#dialog').open)closeDialog();},true);
const params=new URLSearchParams(location.search);
if(params.has('theme')){theme(params.get('theme'),false);const cleanURL=new URL(location.href);cleanURL.searchParams.delete('theme');history.replaceState(null,'',cleanURL);}
if(params.get('view') in routeLabels)state.view=params.get('view');
render();
